"""Small CSV parsing helper used by the reporting scripts."""


def parse(text: str) -> list[list[str]]:
    """Parse CSV text into a list of records, each a list of field strings."""
    # Normalize line endings - convert CRLF to LF
    text = text.replace("\r\n", "\n").replace("\r", "\n")

    rows = []
    i = 0
    n = len(text)

    while i < n:
        # Skip empty lines at the end or between records
        if text[i] == "\n":
            i += 1
            continue

        row = []
        while True:
            if i >= n:
                # End of input, add empty field if needed
                if not row:
                    row.append("")
                break

            if text[i] == '"':
                # Quoted field
                i += 1  # Skip opening quote
                field = ""
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            # Escaped quote
                            field += '"'
                            i += 2
                        else:
                            # End of quoted field
                            i += 1
                            break
                    else:
                        field += text[i]
                        i += 1

                # Skip whitespace after closing quote until comma or newline
                while i < n and text[i] not in [',', '\n']:
                    i += 1

                row.append(field)
            else:
                # Unquoted field
                field = ""
                while i < n and text[i] not in [',', '\n']:
                    field += text[i]
                    i += 1
                row.append(field)

            if i >= n:
                break

            if text[i] == ',':
                i += 1  # Skip comma, continue to next field
            elif text[i] == '\n':
                i += 1  # Skip newline, end of row
                break

        if row:
            rows.append(row)

    return rows

