"""Small CSV parsing helper used by the reporting scripts."""


def parse(text: str) -> list[list[str]]:
    """Parse CSV text into a list of records, each a list of field strings."""
    rows = []

    # Normalize line endings (handle CRLF)
    text = text.replace("\r\n", "\n").replace("\r", "\n")

    i = 0
    n = len(text)

    while i < n:
        # Skip empty lines at the end
        if i == n - 1 and text[i] == "\n":
            break

        row = []

        while True:
            # Find the next field
            field = ""

            if i >= n:
                break

            if text[i] == '"':
                # Quoted field
                i += 1  # skip opening quote
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            # Escaped quote
                            field += '"'
                            i += 2
                        else:
                            # End of quoted field
                            i += 1  # skip closing quote
                            break
                    elif text[i] == '\n':
                        # Embedded newline in quoted field
                        field += '\n'
                        i += 1
                    else:
                        field += text[i]
                        i += 1

                # Skip comma after quoted field (if not end of row)
                if i < n and text[i] == ',':
                    i += 1
                elif i < n and text[i] == '\n':
                    i += 1
                    break
                else:
                    break
            else:
                # Unquoted field - read until comma or newline
                while i < n and text[i] != ',' and text[i] != '\n':
                    field += text[i]
                    i += 1

                if i < n and text[i] == ',':
                    i += 1
                elif i < n and text[i] == '\n':
                    i += 1
                    break
                else:
                    break

            row.append(field)

            # Check if we're done with this row
            if i >= n:
                break
            if text[i] == '\n':
                i += 1
                break

