def parse(text: str) -> list[list[str]]:
    """Parse CSV text into a list of records, each a list of field strings."""
    rows = []

    # Normalize line endings (handle CRLF)
    text = text.replace("\r\n", "\n").replace("\r", "\n")

    i = 0
    n = len(text)

    while i < n:
        # Skip leading empty lines
        if text[i] == '\n':
            i += 1
            continue

        row = []

        while True:
            field = ""

            if i >= n:
                break

            if text[i] == '"':
                # Quoted field
                i += 1  # skip opening quote
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            # Escaped quote
                            field += '"'
                            i += 2
                        else:
                            # End of quoted field
                            i += 1  # skip closing quote
                            break
                    elif text[i] == '\n':
                        # Embedded newline in quoted field
                        field += '\n'
                        i += 1
                    else:
                        field += text[i]
                        i += 1

                # After closing quote, check for comma or newline
                if i < n and text[i] == ',':
                    i += 1
                elif i < n and text[i] == '\n':
                    i += 1
                    row.append(field)
                    break
                else:
                    row.append(field)
                    break
            else:
                # Unquoted field - read until comma or newline
                while i < n and text[i] != ',' and text[i] != '\n':
                    field += text[i]
                    i += 1

                if i < n and text[i] == ',':
                    i += 1
                elif i < n and text[i] == '\n':
                    i += 1
                    row.append(field)
                    break
                else:
                    row.append(field)
                    break

            row.append(field)

        if row:
            rows.append(row)

