"""Small CSV parsing helper used by the reporting scripts."""


def parse(text: str) -> list[list[str]]:
    """Parse CSV text into a list of records, each a list of field strings."""
    rows = []
    i = 0
    n = len(text)

    while i < n:
        # Skip empty lines at the start
        if i >= n:
            break

        # Start a new row
        row = []

        while True:
            if i >= n:
                # End of input
                break

            # Check if we're at a quote (quoted field)
            if text[i] == '"':
                # Quoted field - collect until we find an unescaped closing quote
                i += 1  # skip opening quote
                field = ""

                while i < n:
                    if text[i] == '"':
                        # Check if it's an escaped quote (followed by another quote)
                        if i + 1 < n and text[i + 1] == '"':
                            field += '"'
                            i += 2
                        else:
                            # End of quoted field
                            i += 1
                            # Skip to next comma or end of line
                            while i < n and text[i] not in ',\r\n':
                                i += 1
                            break
                    else:
                        field += text[i]
                        i += 1

                row.append(field)
            else:
                # Unquoted field - collect until comma or end of line
                field = ""
                while i < n and text[i] not in ',\r\n':
                    field += text[i]
                    i += 1

                row.append(field)

            # Check what's next
            if i >= n:
                break
            elif text[i] == ',':
                i += 1  # skip comma, continue to next field
            elif text[i] in '\r\n':
                # Handle line endings (\r\n or \n)
                if text[i] == '\r' and i + 1 < n and text[i + 1] == '\n':
                    i += 2
                else:
                    i += 1
                break  # End of this row

        # Only add non-empty rows (but keep rows with empty fields)
        if row or (len(row) == 0 and False):  # Don't add completely empty rows from blank lines
            # Check if this is truly an empty line (no content at all)
            # We only skip if row is empty AND we didn't process any actual data
            if row:
                rows.append(row)

    return rows

