from window_stats import window_distinct_counts


def check(got, want):
    if got != want:
        raise AssertionError(f"got {got!r}, expected {want!r}")


def test_basic():
    check(window_distinct_counts([1, 2, 1, 3, 2], 3), [2, 3, 3])


